// updateMongoColors.js
// Run with: node updateMongoColors.js

const { MongoClient } = require("mongodb");

// 1) PUT YOUR CONNECTION STRING HERE
const MONGO_URI = "your_atlas_connection_string_here";
const DB_NAME = "survey";
const COLLECTION = "surveyentries";

// 2) MAP usage → new colors
const COLOR_MAP = {
    residential: { color: '#4895EF' }, // Soft Professional Blue
    commercial: { color: '#4361EE' }, // Indigo (strong + premium)
    industrial: { color: '#3A0CA3' }, // Deep Violet (distinct)
    institutional: { color: '#4CC9F0' }, // Sky Blue Accent
    government: { color: '#7209B7' }, // Royal Purple
    hospital: { color: '#F72585' }, // Magenta Highlight (stands out)
    'community hall': { color: '#8C5E99' }, // Muted Purple-Grey (professional)
    'entertainment hall': { color: '#B892FF' }, // Light Lavender (soft + visible)
    'without cc': { color: '#A0A4B8' }, // Cool Grey
    'change of properties': { color: '#89C2D9' }, // Muted Cyan (easy to notice)
    'unauthorized towers': { color: '#6C757D' }, // Dark Professional Grey
    default: { color: '#4895EF' }  // Professional Blue (fallback)
};
(async () => {
  const client = new MongoClient(MONGO_URI);
  await client.connect();
  const col = client.db(DB_NAME).collection(COLLECTION);

  console.log("Connected. Updating colors...");

  const docs = await col.find({}).toArray();

  for (const doc of docs) {
    const usage = (doc.usage || "default").toLowerCase();
    const mapKey = COLOR_MAP[usage] ? usage : "default";
    const { hex, kml } = COLOR_MAP[mapKey];

    // Replace all KML color tags
    const oldKml = doc.kmlData || "";
    const updatedKml = oldKml.replace(
      /<color>[0-9A-Fa-f]{8}<\/color>/g,
      `<color>${kml}</color>`
    );

    await col.updateOne(
      { _id: doc._id },
      {
        $set: {
          kmlData: updatedKml,
          "style.color": hex
        }
      }
    );

    console.log(`Updated: ${doc._id} [${usage}] → ${hex} / ${kml}`);
  }

  console.log("All colors updated successfully.");
  await client.close();
})();
